import urllib.parse

def parse_query(qs):
    """
    Parses a URL query string into a dictionary.
    Repeated keys are stored in a list.
    Percent-encoded characters and '+' (representing space) are decoded.
    """
    if not qs:
        return {}

    # Parse the query string
    parsed = urllib.parse.parse_qs(qs, keep_blank_values=True)

    # Convert the resulting list values to strings (or lists of strings)
    # and handle the case where a key appears only once (it's a string, not a list)
    result = {}
    for key, values in parsed.items():
        if len(values) == 1:
            result[key] = values[0]
        else:
            result[key] = values

    return result
