def count_paths(m, n):
    # Create a 2D array to store the number of paths
    dp = [[0 for _ in range(n)] for _ in range(m)]

    # There is only 1 way to reach any cell in the first row or first column
    for i in range(m):
        dp[i][0] = 1
    for j in range(n):
        dp[0][j] = 1

    # Fill the rest of the table
    for i in range(1, m):
        for j in range(1, n):
            dp[i][j] = dp[i-1][j] + dp[i][j-1]

    return dp[m-1][n-1]
```

