def parse_ini(text):
    """
    Parses an INI-style configuration file into a dictionary.
    """
    config = {}
    current_section = None

    for line in text.splitlines():
        line = line.strip()

        # Skip empty lines
        if not line:
            continue

        # Skip comments
        if line.startswith(';') or line.startswith('#'):
            continue

        # Check for section header
        if line.startswith('[') and line.endswith(']'):
            current_section = line[1:-1].strip()
            config[current_section] = {}
            continue

        # Parse key-value pair
        if '=' in line:
            key, value = line.split('=', 1)
            key = key.strip()
            value = value.strip()

            if current_section is not None:
                config[current_section][key] = value
            else:
                # Handle global keys if they exist (optional, usually ignored or put in a 'global' section)
                # For this implementation, we will ignore them or put them in a 'default' section
                if 'default' not in config:
                    config['default'] = {}
                config['default'][key] = value

    return config
```

