import heapq

def topk(items, k):
    if k <= 0:
        return []
    if k >= len(items):
        return sorted(items, reverse=True)

    # Use a min-heap to keep track of the k largest items
    # The heap will store tuples of (value, index) to handle duplicates correctly
    heap = []
    for i, item in enumerate(items):
        if len(heap) < k:
            heapq.heappush(heap, (item, i))
        else:
            # If the current item is larger than the smallest in the heap
            if item > heap[0][0]:
                heapq.heappop(heap)
                heapq.heappush(heap, (item, i))

    # Extract the items from the heap and sort them in descending order
    result = [item for item, _ in heap]
    result.sort(reverse=True)
    return result
```

