def strip_comments(code):
    lines = code.splitlines()
    result = []
    in_single_quote = False
    in_double_quote = False
    escape_next = False

    for line in lines:
        i = 0
        while i < len(line):
            char = line[i]

            if escape_next:
                escape_next = False
                i += 1
                continue

            if char == '\\':
                escape_next = True
                i += 1
                continue

            if not in_single_quote and not in_double_quote:
                if char == '#':
                    break
                elif char == "'":
                    in_single_quote = True
                elif char == '"':
                    in_double_quote = True
            else:
                if (char == "'" and not in_double_quote) or (char == '"' and not in_single_quote):
                    in_single_quote = False
                    in_double_quote = False

            i += 1

        result.append(line[:i])

    return "\n".join(result)
```

