function debounceCount(fn, ms) {
    let timer;
    let count = 0;

    function debounced() {
        count++;
        clearTimeout(timer);
        timer = setTimeout(() => {
            fn(count);
            count = 0;
        }, ms);
    }

    function flush() {
        clearTimeout(timer);
        if (count > 0) {
            fn(count);
            count = 0;
        }
    }

    return {
        call: debounced,
        flush: flush
    };
}

