module.exports = function allSettledCounts(promises) {
  return new Promise((resolve) => {
    let fulfilled = 0;
    let rejected = 0;
    let completed = 0;

    if (promises.length === 0) {
      resolve({ fulfilled, rejected });
      return;
    }

    promises.forEach((promise) => {
      Promise.resolve(promise).then(
        () => {
          fulfilled++;
        },
        () => {
          rejected++;
        }
