export function invert(o: Record<string, string>): Record<string, string> {
  const result: Record<string, string> = {};
  for (const key in o) {
    if (Object.prototype.hasOwnProperty.call(o, key)) {
      const value = o[key];
      if (value !== undefined) {
        result[value] = key;
      }
    }
  }
  return result;
}
