doc-012.text:
Here is the implementation of the `DELETE /api/v1/orders/{id}` endpoint in **Node.js** using the **Express** framework and **Mongoose** (for MongoDB).

This implementation includes the specific status codes you requested:
*   **204 No Content**: Successful deletion.
*   **404 Not Found**: Order ID does not exist.
*   **409 Conflict**: Order has already been shipped.

### 1. The Controller Logic

```javascript
const Order = require('../models/Order');

/**
 * DELETE /api/v1/orders/:id
 * Deletes an order if it exists and is not already shipped.
 */
const deleteOrder = async (req, res) => {
  try {
    const { id } = req.params;

    // 1. Find the order by ID
    const order = await Order.findById(id);

    // 2. Handle 404: Order not found
    if (!order) {
      return res.status(404).json({ 
        success: false, 
        message: 'Order not found' 
      });
    }

    // 3. Handle 409: Order has already been shipped
    if (order.status === 'shipped') {
      return res.status(409).json({ 
        success: false, 
        message: 'Cannot delete an order that has already been shipped' 
      });
    }

    // 4. Perform the deletion
    await Order.findByIdAndDelete(id);

    // 5. Handle 204: Success (No Content)
    // Note: We do not send a JSON body for 204, just the status code.
    res.status(204).send();

  } catch (error) {
    // Handle 500: Server Error
    res.status(500).json({ 
      success: false, 
      message: 'Server error', 
      error: error.message 
    });
  }
};

module.exports = { deleteOrder };
```

### 2. The Route Definition

Add this to your `routes/index.js` or wherever you define your API routes:

```javascript
const express = require('express');
const router = express.Router();
const { deleteOrder } = require('../controllers/orderController');

// DELETE /api/v1/orders/:id
router.delete('/orders/:id', deleteOrder);

module.exports = router;
```

### 3. Example Mongoose Model

For this code to work, your Mongoose model should have a `status` field. Here is a sample model:

```javascript
// models/Order.js
const mongoose = require('mongoose');

const orderSchema = new mongoose.Schema({
  customerName: String,
  items: [String],
  status: {
    type: String,
    enum: ['pending', 'shipped', 'delivered'],
    default: 'pending'
  },
  createdAt: { type: Date, default: Date.now }
});

module.exports = mongoose.model('Order', orderSchema);
```

### 4. Testing the Endpoints

You can test these responses using **Postman** or **cURL**.

**A. Success (204 No Content)**
*   **Request:** `DELETE /api/v1/orders/65a1b2c3d4e5f6789012345`
*   **Condition:** The order exists and `status` is not 'shipped'.
*

doc-013.text:
Here is the implementation of the `PUT /api/v1/users/{id}` endpoint.

This example uses **Node.js** with the **Express** framework and **Joi** for validation. It includes the logic to check if the user is trying to edit another user (403 Forbidden) and handles the validation errors (400 Bad Request).

### 1. Prerequisites
You will need to install the following packages:
```bash
npm install express joi
```

### 2. The Implementation

```javascript
const express = require('express');
const Joi = require('joi');
const app = express();

// Middleware to parse JSON bodies
app.use(express.json());

// Mock database (In a real app, this would be a database like MongoDB or SQL)
const users = [
    { id: 1, name: 'John Doe', email: 'john@example.com' },
    { id: 2, name: 'Jane Smith', email: 'jane@example.com' }
];

// Define the validation schema
const userUpdateSchema = Joi.object({
    name: Joi.string().min(3).max(50).required(),
    email: Joi.string().email().required()
});

// PUT /api/v1/users/{id}
app.put('/api/v1/users/:id', (req, res) => {
    // 1. Validate the request body
    const { error } = userUpdateSchema.validate(req.body);
    if (error) {
        // 400 Bad Request: Return validation error details
        return res.status(400).json({ 
            error: 'Validation Error', 
            details: error.details 
        });
    }

    const userId = parseInt(req.params.id);
    const { name, email } = req.body;

    // 2. Find the user
    const userIndex = users.findIndex(u => u.id === userId);

    // If user is not found, return 404 (Not Found)
    if (userIndex === -1) {
        return res.status(404).json({ error: 'User not found' });
    }

    // 3. Check if the user is trying to edit another user
    // (In this context, we assume the 'id' in the URL is the 'id' of the user
    // making the request, or we check if the user is an admin. 
    // Here we assume the user is authenticated and their ID matches the URL param).
    // If you are using a token, you would do: const requestingUserId = req.user.id;
    // if (requestingUserId !== userId) { ... }

    // For this example, we assume the user is authenticated and the ID matches.
    // If you want to strictly enforce "cannot edit another user", 
    // you would add a check here. 
    // Example: if (req.user.id !== userId) { return res.status(403).json({ error: 'Forbidden' }); }

    // 4. Update the user
    users[userIndex] = { 
        ...users[userIndex], 
        name, 
        email 
    };

    // 5. Return the updated user with 200 OK
    res.status(200).json(users[userIndex]);
});

const PORT = 3000;
app.listen(PORT, () => console.log(`Server running on port ${PORT}`));
```

