import React, { useEffect, useState } from 'react';
import { View, Text, Button, Linking, Alert } from 'react-native';

const OpenExternalUrl = () => {
  const [isSupported, setIsSupported] = useState(false);

  useEffect(() => {
    const checkUrl = async () => {
      const supported = await Linking.canOpenURL('https://www.google.com');
      setIsSupported(supported);
    };

    checkUrl();
  }, []);

  const handlePress = async () => {
    if (!isSupported) {
      Alert.alert('Error', "Don't know how to open this URL");
      return;
    }

    try {
      await Linking.openURL('https://www.google.com');
    } catch (error) {
      Alert.alert('Error', `Something went wrong: ${error.message}`);
    }
  };

  return (
    <View style={{ flex: 1, justifyContent: 'center', alignItems: 'center' }}>
      <Text>External URL Linking Example</Text>
      <Button title="Open Google" onPress={handlePress} />
    </View>
  );
};

export default OpenExternalUrl;
